def circ_ave(a0, a1):
    """see http://stackoverflow.com/a/1416826/113195"""
    r = (a0+a1)/2., ((a0+a1+360)/2.)%360
    if min(abs(a1-r[0]), abs(a0-r[0])) < min(abs(a0-r[1]), abs(a1-r[1])):
        return r[0]
    else:
        return r[1]

